import{t as e}from"./jsx-runtime-CY_jTiqj.js";import{A as t,C as n,E as r,M as i,N as a,O as o,P as s,_ as c,b as l,k as u,l as d,n as f,o as p,p as m,t as h,v as g,w as _}from"./shared-JA1PGxXr.js";import{t as v}from"./CodeEditor-DqHMt3P8.js";var y=e();function b({module:e}){return(0,y.jsxs)(a,{children:[(0,y.jsx)(i,{chip:e??`Блок 4 · Собираем свой Planner`,title:`Считаем статистику задач`,intro:`Посчитаем текущее состояние Planner и заменим заглушку команды stats реальной сводкой.`,variant:`project`}),(0,y.jsxs)(s,{number:`00`,title:`От списка задач к общей картине`,children:[(0,y.jsx)(o,{children:`По маршруту предыдущих занятий у нас должен быть Planner с добавлением, поиском и завершением задач. Перед практикой убедимся, что эти команды работают в нашем main.py. Теперь посмотрим на список целиком.`}),(0,y.jsx)(u,{variant:`connected`,items:[{title:`Точка старта`,description:`По плану 16–19 подготовлены add, list, find, done и search; это нужно проверить в своём main.py. Команда stats пока заглушка, каждая задача хранит is_done.`},{title:`Новый вопрос`,description:`Как узнать, сколько задач сейчас всего, сколько завершено и какую долю они составляют, даже если список пуст?`},{title:`Результат`,description:`Команда stats показывает total, completed, left и процент по текущему списку, не меняя сами задачи.`}]}),(0,y.jsx)(`p`,{children:`Сначала отделим состояние карточек от действий, которые к нему привели. Затем разберём один проход по списку, отдельно посчитаем процент и только после этого заменим заглушку уже доступной команды stats. Меню, допустимые команды и прежние операции Planner сохраняются.`})]}),(0,y.jsxs)(s,{number:`01`,title:`Карточка хранит состояние, команда создаёт событие`,children:[(0,y.jsxs)(`p`,{children:[`Поле `,(0,y.jsx)(`code`,{children:`is_done`}),` отвечает на вопрос о карточке сейчас: значение `,(0,y.jsx)(`code`,{children:`True`}),` означает, что задача выполнена, а `,(0,y.jsx)(`code`,{children:`False`}),` означает, что она ещё открыта. Команда `,(0,y.jsx)(`code`,{children:`done`}),` описывает действие пользователя. Эти ответы связаны, но это не одно и то же.`]}),(0,y.jsxs)(`p`,{children:[`Представим список отметок на бумажном контрольном листе. Галочка показывает состояние строки. Число нажатий на ручку не показывает, сколько строк отмечено: можно дважды обвести одну галочку, но строка всё равно одна. Так же повторный `,(0,y.jsx)(`code`,{children:`done`}),` для уже выполненной задачи не создаёт ещё одну задачу и не делает её «выполненной дважды».`]}),(0,y.jsx)(t,{rows:[[`Путь А: done → id 4`,`Было: №4 False, №9 False. Стало: №4 True, №9 False. Выполнена одна карточка.`],[`Путь Б: трижды done → id 4`,`Было то же самое. Стало: №4 True, №9 False. Выполнена всё ещё одна карточка.`]]}),(0,y.jsxs)(`p`,{children:[`В обоих путях отметка стоит у одной и той же карточки. Предскажите `,(0,y.jsx)(`code`,{children:`completed`}),` прежде, чем выбрать ответ. Если после любого из путей завершить ещё и №9, `,(0,y.jsx)(`code`,{children:`completed`}),` станет равным двум: поменялось состояние другой карточки, а не число нажатий.`]}),(0,y.jsx)(l,{question:`После трёх команд done с id 4 у №4 стоит True, у №9 False. Сколько завершённых задач?`,options:[`3: команду ввели три раза`,`1: True находится у одной карточки`,`0: повторная команда сбросила результат`],correctIndex:1,explanation:`№4 учтён один раз, №9 ещё открыта. Считаем записи со значением True, а не количество вызовов done.`}),(0,y.jsxs)(r,{tone:`info`,children:[(0,y.jsx)(`code`,{children:`done`}),` меняет состояние одной найденной записи. `,(0,y.jsx)(`code`,{children:`stats`}),` читает состояния всех записей. Счётчик команд для этой задачи не нужен.`]})]}),(0,y.jsxs)(s,{number:`02`,title:`Счётчики согласуются за один проход`,children:[(0,y.jsxs)(`p`,{children:[`Нам нужны три числа. `,(0,y.jsx)(`code`,{children:`total`}),` означает число всех карточек, `,(0,y.jsx)(`code`,{children:`completed`}),` означает число карточек с истинным `,(0,y.jsx)(`code`,{children:`is_done`}),`, а `,(0,y.jsx)(`code`,{children:`left`}),` означает число незавершённых карточек. Эти значения должны совпадать с тем, что мы увидим в полном списке, а не только с тем, что показала последняя команда.`]}),(0,y.jsxs)(`p`,{children:[`Каждый элемент мы встречаем один раз. Перед циклом начинаем общий счёт с нуля. Для каждой записи добавляем единицу к `,(0,y.jsx)(`code`,{children:`total`}),`; если поле истинно, добавляем единицу и к `,(0,y.jsx)(`code`,{children:`completed`}),`. После цикла незавершённое число получается вычитанием: `,(0,y.jsx)(`code`,{children:`left = total - completed`}),`. Так мы не заводим третий условный счётчик для того, что уже следует из первых двух.`]}),(0,y.jsx)(t,{rows:[[`До for`,`total = 0, completed = 0. Счётчики создаются заново перед каждым вызовом функции.`],[`На каждой карточке`,`total += 1 всегда; completed += 1 только когда task["is_done"] истинно.`],[`После for`,`left = total - completed; проверка: total = completed + left.`]]}),(0,y.jsxs)(`p`,{children:[`Счётчик похож на сумму в кассовом чеке: каждый новый товар добавляет одну позицию, а не стирает число предыдущих товаров. Поэтому строка `,(0,y.jsx)(`code`,{children:`completed += 1`}),` сохраняет уже набранное и увеличивает его на единицу. Присваивание `,(0,y.jsx)(`code`,{children:`completed = 1`}),` каждый раз заменило бы прежний итог, и список с несколькими выполненными карточками ошибочно дал бы только единицу.`]}),(0,y.jsxs)(`p`,{children:[`Посмотрим трассу на трёх карточках Planner со статусами `,(0,y.jsx)(`code`,{children:`False, True, True`}),`. Нажимайте «Дальше» и следите за парой счётчиков. На второй выполненной карточке мы должны получить два, а не один.`]}),(0,y.jsx)(g,{code:`tasks = [{"is_done": False}, {"is_done": True}, {"is_done": True}]
total = 0
completed = 0
for task in tasks:
    total += 1
    if task["is_done"]:
        completed += 1
left = total - completed`,steps:[{line:2,note:`До цикла нули: ещё ни одну карточку не просмотрели.`,vars:{total:`0`,completed:`0`}},{line:5,note:`Первая карточка False: total вырос до 1, условие не пройдёт.`,vars:{total:`1`,completed:`0`,is_done:`False`}},{line:5,note:`Вторая карточка True: total вырос до 2.`,vars:{total:`2`,completed:`0`,is_done:`True`}},{line:6,note:`После второй карточки completed увеличился до 1.`,vars:{total:`2`,completed:`1`,is_done:`True`}},{line:5,note:`Третья карточка True: total вырос до 3, completed пока равен 1.`,vars:{total:`3`,completed:`1`,is_done:`True`}},{line:6,note:`Вторая True увеличивает прежнюю единицу: completed теперь 2.`,vars:{total:`3`,completed:`2`,is_done:`True`}},{line:7,note:`После цикла осталось 3 - 2 = 1 открытая задача.`,vars:{total:`3`,completed:`2`,left:`1`}}]}),(0,y.jsxs)(`p`,{children:[`Для любого списка после подсчёта должно выполняться равенство `,(0,y.jsx)(`code`,{children:`total = completed + left`}),`. Это проверка согласованности, а не дополнительная операция в цикле. На пустом списке все три числа равны нулю: ни одна карточка не обработана, ни одна не завершена и ни одна не ожидает.`]}),(0,y.jsx)(l,{question:`Теперь без трассы: статусы True, False, True, False. Какие total, completed, left получатся?`,options:[`4, 2, 2`,`4, 1, 3`,`2, 2, 0`],correctIndex:0,explanation:`Четыре карточки просмотрели, две с True, две остались открытыми. 4 = 2 + 2.`}),(0,y.jsxs)(`p`,{children:[`Такой подсчёт также показывает границы: `,(0,y.jsx)(`code`,{children:`completed`}),` не может быть больше `,(0,y.jsx)(`code`,{children:`total`}),`. При повторном вызове счётчики начинаются с нуля и читают текущие карточки заново. После `,(0,y.jsx)(`code`,{children:`add`}),`или `,(0,y.jsx)(`code`,{children:`done`}),` изменится сам список или его поля, поэтому следующий результат может отличаться.`]})]}),(0,y.jsxs)(s,{number:`03`,title:`Функция возвращает сводку, а не печатает её`,children:[(0,y.jsxs)(`p`,{children:[`Функция `,(0,y.jsx)(`code`,{children:`build_statistics(tasks)`}),` получает список Planner и возвращает словарь с тремя согласованными числами. Словарь удобен как один результат: вместо нескольких несвязанных ответов дальше передаётся одна сводка с ключами `,(0,y.jsx)(`code`,{children:`total`}),`, `,(0,y.jsx)(`code`,{children:`completed`}),` и `,(0,y.jsx)(`code`,{children:`left`}),`.`]}),(0,y.jsx)(`p`,{children:`Это похоже на заполненную квитанцию, которую кассир передаёт следующему сотруднику. Внутри расчёта мы заполняем поля, но не объявляем их вслух. Получатель сам решает, как показать значения. Для нашей программы получателем станет ветвь меню, которая напечатает понятные подписи.`}),(0,y.jsx)(t,{rows:[[`return statistics`,`Передаёт словарь вызывающему коду, где можно прочитать его ключи.`],[`print(statistics)`,`Показывает словарь человеку, но сам по себе не передаёт его другой функции.`],[`local counters`,`Создаются при каждом вызове и описывают только переданный список.`]]}),(0,y.jsxs)(`p`,{children:[`Здесь важно различать `,(0,y.jsx)(`code`,{children:`return`}),` и `,(0,y.jsx)(`code`,{children:`print`}),`. После одного лишь `,(0,y.jsx)(`code`,{children:`print`}),` функция обычно вернёт `,(0,y.jsx)(`code`,{children:`None`}),`: следующая функция не сможет прочитать три числа по ключам. После`,(0,y.jsx)(`code`,{children:`return`}),` вызывающая сторона получает именно словарь и решает, как его показывать.`]}),(0,y.jsxs)(`p`,{children:[`Например, если передать две карточки со статусами `,(0,y.jsx)(`code`,{children:`True, False`}),`, вызывающий код должен получить словарь `,(0,y.jsx)(`code`,{children:`{"total": 2, "completed": 1, "left": 1}`}),`. Это описание ожидаемого результата, а не готовая реализация вашей функции. Ключи должны совпадать буквально: обращение к несуществующему`,(0,y.jsx)(`code`,{children:`"complete"`}),` вместо `,(0,y.jsx)(`code`,{children:`"completed"`}),` приведёт к ошибке.`]}),(0,y.jsx)(m,{prompt:`Соедините каждое действие с его назначением. Эти роли понадобятся при переносе функций в run().`,leftTitle:`Действие`,rightTitle:`Результат`,pairs:[{left:`total += 1`,right:`Учитывает очередную карточку в общем количестве`},{left:`return statistics`,right:`Передаёт словарь вызывающему коду`},{left:`print(statistics)`,right:`Отображает словарь в терминале`}],explanation:`Счётчик обновляется внутри расчёта, return отдаёт результат, а print нужен только на стороне интерфейса.`}),(0,y.jsxs)(`p`,{children:[(0,y.jsx)(`code`,{children:`build_statistics`}),` только читает переданные карточки: она не меняет `,(0,y.jsx)(`code`,{children:`is_done`}),`, не печатает и не хранит прошлый результат. Поэтому её можно вызвать отдельно от меню и после изменения списка. Известная функция `,(0,y.jsx)(`code`,{children:`calculate_study_minutes(durations)`}),` по-прежнему отдельно считает минуты, а новую команду `,(0,y.jsx)(`code`,{children:`calc`}),` мы не добавляем.`]}),(0,y.jsxs)(`p`,{children:[`Проверить отсутствие изменений можно сравнением самих карточек до и после подсчёта: значения`,(0,y.jsx)(`code`,{children:`id`}),`, `,(0,y.jsx)(`code`,{children:`title`}),`, `,(0,y.jsx)(`code`,{children:`priority`}),` и `,(0,y.jsx)(`code`,{children:`is_done`}),` должны остаться прежними. Допустим, до первого вызова у двух карточек статусы `,(0,y.jsx)(`code`,{children:`False, True`}),`. Если затем команда`,(0,y.jsx)(`code`,{children:`done`}),` изменит первую на `,(0,y.jsx)(`code`,{children:`True`}),`, повторный вызов должен получить уже две выполненные карточки. Функция не запоминает прошлую единицу и не меняет карточки сама: она каждый раз заново читает аргумент и формирует новый словарь. Это легко проверить без запуска всего меню.`]})]}),(0,y.jsxs)(s,{number:`04`,title:`Доля становится процентом`,children:[(0,y.jsxs)(`p`,{children:[`Процент отвечает на вопрос: какую часть составляет выбранное количество от общего? Сначала мы сравниваем часть с целым и получаем долю. Затем выражаем эту долю на шкале из ста. В статистике задач часть равна`,(0,y.jsx)(`code`,{children:`completed`}),`, а целое равно `,(0,y.jsx)(`code`,{children:`total`}),`.`]}),(0,y.jsxs)(`p`,{children:[`Представим полоску из четырёх одинаковых клеток: `,(0,y.jsx)(`code`,{children:`■□□□`}),`. Закрашена одна из четырёх, то есть четверть. Если представить тот же участок на шкале из ста клеток, закрашены были бы 25: четверть от ста. Поэтому `,(0,y.jsx)(`code`,{children:`1 / 4 = 0.25`}),` (доля), а `,(0,y.jsx)(`code`,{children:`0.25 * 100 = 25.0`}),` (процент).`]}),(0,y.jsx)(t,{rows:[[`1 выполнена из 4`,`■□□□ → 1 / 4 → 0.25 → 25.0%`],[`2 выполнены из 5`,`■■□□□ → 2 / 5 → 0.4 → 40.0%`],[`3 выполнены из 3`,`■■■ → 3 / 3 → 1.0 → 100.0%`]]}),(0,y.jsxs)(`p`,{children:[`В Python оператор `,(0,y.jsx)(`code`,{children:`/`}),` выполняет дробное деление. Поэтому для одной выполненной проверки из трёх сначала получается примерно `,(0,y.jsx)(`code`,{children:`0.3333`}),`, а умножение на сто переводит её в процент, примерно`,(0,y.jsx)(`code`,{children:`33.3333`}),`. Мы округляем уже итоговый процент до одного знака: `,(0,y.jsx)(`code`,{children:`33.3`}),`. Если сначала округлить долю до `,(0,y.jsx)(`code`,{children:`0.3`}),`, после умножения получится `,(0,y.jsx)(`code`,{children:`30.0`}),`, что заметно искажает ответ.`]}),(0,y.jsxs)(`p`,{children:[`Есть два равноценных порядка при ненулевом целом: `,(0,y.jsx)(`code`,{children:`part / whole * 100`}),` и`,(0,y.jsx)(`code`,{children:`part * 100 / whole`}),`. В обоих случаях мы используем обычное деление и сохраняем масштаб. Не путаем их с `,(0,y.jsx)(`code`,{children:`whole / part * 100`}),`, которое меняет местами часть и целое, или с целочисленным делением `,(0,y.jsx)(`code`,{children:`//`}),`, которое в маленьких долях может отбросить дробную часть.`]}),(0,y.jsx)(c,{code:`part = 1
whole = 3
ratio = part / whole
print(round(ratio * 100, 1))
print(round(ratio, 1) * 100)`,output:`33.3
30.0`,hint:`Округляем один раз: сравните округление уже переведённого процента с округлением доли.`}),(0,y.jsxs)(`p`,{children:[`Сначала предскажите две строки и лишь затем раскройте вывод. Разница между `,(0,y.jsx)(`code`,{children:`33.3`}),` и`,(0,y.jsx)(`code`,{children:`30.0`}),` показывает, почему округляем процент в конце. Словарь счётчиков оставляем с целыми числами, а функция процента возвращает число, без знака `,(0,y.jsx)(`code`,{children:`%`}),`. Знак добавим при печати в меню.`]}),(0,y.jsx)(_,{title:`Соберите расчёт для другой доли`,prompt:`У нас уже заданы done = 2 и all_items = 7. Выберите правильные строки и их порядок: доля, процент, вывод. Лишнюю строку с ранним округлением оставьте.`,pieces:[{id:`ratio`,code:`share = done / all_items`},{id:`percent`,code:`percent = round(share * 100, 1)`},{id:`print`,code:`print(percent)`},{id:`early`,code:`percent = round(share, 1) * 100`,note:`Лишняя строка: округление доли до перевода в проценты`}],correctOrder:[`ratio`,`percent`,`print`],explanation:`Сначала 2 / 7 ≈ 0.2857, затем 28.6 процента и выводим 28.6. Раннее округление 0.3 дало бы 30.0.`,incorrectExplanation:`Проверьте зависимость: сначала нужна share, из неё получаем percent, после этого можно печатать число.`}),(0,y.jsx)(`p`,{children:`Теперь мы умеем и предсказывать результат, и собирать порядок вычислений. В задаче платформы этот же порядок понадобится применить к значениям из словаря, полученного предыдущей функцией.`})]}),(0,y.jsxs)(s,{number:`05`,title:`Пустой список обрабатываем до деления`,children:[(0,y.jsxs)(`p`,{children:[`Если задач нет, `,(0,y.jsx)(`code`,{children:`total`}),` равен нулю. Значение `,(0,y.jsx)(`code`,{children:`completed / total`}),` в этом случае вычислить нельзя. Для интерфейса Planner мы заранее выбираем договор: пустой список показывает`,(0,y.jsx)(`code`,{children:`0.0`}),` процента. Это решение программы для отсутствия задач, а не результат деления на ноль.`]}),(0,y.jsxs)(`p`,{children:[`В функции `,(0,y.jsx)(`code`,{children:`completion_percent(statistics)`}),` порядок действий защищает этот случай. Сначала читаем`,(0,y.jsx)(`code`,{children:`total`}),`. Если он равен нулю, сразу возвращаем `,(0,y.jsx)(`code`,{children:`0.0`}),`. Только иначе читаем`,(0,y.jsx)(`code`,{children:`completed`}),`, делим и округляем. Условие после вычисления не поможет: ошибка уже возникнет на строке деления.`]}),(0,y.jsx)(t,{rows:[[`total == 0`,`Сразу возвращаем 0.0. До выражения с / выполнение не доходит.`],[`total > 0`,`Делим completed на total, умножаем на 100 и округляем до 1 знака.`]]}),(0,y.jsx)(`p`,{children:`Представим корзину для сбора листов на столе. Если в ней нет ни одного листа, нельзя честно спросить, какую долю всех листов составляют собранные. Программа всё равно может показать заранее согласованное пустое значение, чтобы пользователь видел понятный результат. Мы не подменяем знаменатель единицей и не называем это вычисленной долей.`}),(0,y.jsxs)(`p`,{children:[`Функция возвращает именно числовое `,(0,y.jsx)(`code`,{children:`0.0`}),`. Для половины и трети она применяет обычную формулу; тестируя оба случая, мы различаем договорную пустоту и вычисленный процент. Если вернуть текст`,(0,y.jsx)(`code`,{children:`"0.0%"`}),`, тип ответа изменится: вызывающему коду неудобно будет считать дальше.`]}),(0,y.jsx)(n,{code:`def average_score(scores):
    total = 0
    for score in scores:
        total += score
    average = total / len(scores)
    if len(scores) == 0:
        return 0.0
    return round(average, 1)`,question:`Почему функция падает на пустом списке, хотя в ней есть проверка?`,options:[`Пустой список нельзя передать параметром`,`Проверка стоит после строки, где len(scores) уже делит на ноль`,`Округление всегда требует хотя бы одно число`],correctIndex:1,explanation:`Мы должны проверить делитель до вычисления. Исправление переносит условие перед делением; для пустого списка выбранный ответ возвращается сразу.`,fix:`def average_score(scores):
    if len(scores) == 0:
        return 0.0
    total = 0
    for score in scores:
        total += score
    average = total / len(scores)
    return round(average, 1)`}),(0,y.jsxs)(`p`,{children:[`В примере проверяются средние баллы, а не статистика Planner. Нас интересует только общий порядок защиты: сначала определяем, разрешено ли деление, затем выполняем его. В собственной функции мы применим тот же порядок к `,(0,y.jsx)(`code`,{children:`total`}),`, не копируя пример целиком.`]})]}),(0,y.jsxs)(s,{number:`06`,title:`Ветка stats считает полный список и выводит сводку`,children:[(0,y.jsxs)(`p`,{children:[`Во время одного запуска функция `,(0,y.jsx)(`code`,{children:`run()`}),` владеет общим списком `,(0,y.jsx)(`code`,{children:`tasks`}),`. Ветка меню получает его после команды `,(0,y.jsx)(`code`,{children:`stats`}),`, вызывает `,(0,y.jsx)(`code`,{children:`build_statistics(tasks)`}),`, передаёт словарь в `,(0,y.jsx)(`code`,{children:`completion_percent(statistics)`}),` и показывает четыре подписи. Вычисления возвращают данные; именно ветвь меню отвечает за пользовательский текст.`]}),(0,y.jsxs)(`p`,{children:[`Важно передавать полный список. Команда `,(0,y.jsx)(`code`,{children:`search`}),` временно получает список совпадений для показа, но это выборка, не новое состояние Planner. Если у нас две задачи, а поиск нашёл одну, статистика всё равно охватывает обе. Иначе экран сказал бы, что выполнена одна из одной, хотя в Planner есть вторая карточка.`]}),(0,y.jsx)(l,{question:`В Planner две задачи: «Письмо» (True), «Покупки» (False). search по «Письмо» показал одну. Что покажет следующий stats?`,options:[`Всего: 1, Выполнено: 1, Осталось: 0, Процент: 100.0%`,`Всего: 2, Выполнено: 1, Осталось: 1, Процент: 50.0%`,`Всего: 2, Выполнено: 2, Осталось: 0, Процент: 100.0%`],correctIndex:1,explanation:`search не удаляет и не заменяет основной tasks. В stats передаём все две карточки, поэтому завершена одна из двух.`}),(0,y.jsxs)(`p`,{children:[`Если `,(0,y.jsx)(`code`,{children:`tasks`}),` пока пуст, обе функции тоже должны отработать: сводка вернёт три нуля, а процентная функция выберет договорные `,(0,y.jsx)(`code`,{children:`0.0`}),` до деления. Поэтому команда `,(0,y.jsx)(`code`,{children:`stats`}),` может безопасно показать пустое состояние ещё до первой задачи.`]}),(0,y.jsxs)(`p`,{children:[`Схема показывает путь данных от состояния карточек до строк меню. Сначала мы читаем весь `,(0,y.jsx)(`code`,{children:`tasks`}),`, затем получаем словарь счётчиков, после чего вычисляем процент и показываем показатели. Узлы описывают разные роли, а не дополнительные хранилища или новые команды.`]}),(0,y.jsx)(h,{caption:`Как текущие задачи превращаются в строки команды stats`,orientation:`vertical`,children:(0,y.jsxs)(p,{label:`Полный список tasks передаётся в подсчёт, сводка передаётся в процент, результат показывается в меню`,orientation:`vertical`,children:[(0,y.jsx)(d,{title:`Список задач`,shape:`process`,children:(0,y.jsx)(`p`,{children:`2 задачи: 1 выполнена, 1 открыта`})}),(0,y.jsx)(f,{label:`передаём все записи`}),(0,y.jsx)(d,{title:`build_statistics(tasks)`,children:`Читает статусы и возвращает total, completed, left`}),(0,y.jsx)(f,{label:`передаём словарь`}),(0,y.jsx)(d,{title:`completion_percent(statistics)`,children:`Вычисляет процент из completed и total`}),(0,y.jsx)(f,{label:`run печатает сводку`}),(0,y.jsx)(d,{title:`Вывод команды stats`,children:`Всего: 2, Выполнено: 1, Осталось: 1, Процент выполнения: 50.0%`})]})}),(0,y.jsxs)(`p`,{children:[`По схеме можно проверить, что ветвь меню использует один список, а функции не подменяют его копией или результатом поиска. Вернувшийся словарь сохраняет целые счётчики; отдельное число процента не меняет его. Если список не изменился, повторный вызов показывает те же значения. После нового `,(0,y.jsx)(`code`,{children:`add`}),` или`,(0,y.jsx)(`code`,{children:`done`}),` следующий вызов пересчитывает текущее состояние.`]}),(0,y.jsxs)(`p`,{children:[`В ожидаемом проекте после занятия 19 `,(0,y.jsx)(`code`,{children:`show_menu()`}),` уже показывает `,(0,y.jsx)(`code`,{children:`stats`}),`, проверка разрешённых имён пропускает команду, а `,(0,y.jsx)(`code`,{children:`run()`}),` отвечает заглушкой. Перед работой это нужно проверить на своём файле. Мы заменим тело существующей ветви четырьмя подписанными строками; новые команды, второй `,(0,y.jsx)(`code`,{children:`tasks`}),` и отдельный `,(0,y.jsx)(`code`,{children:`handle_stats`}),` не нужны.`]}),(0,y.jsx)(v,{caption:`Независимый пример: проверки регистрации на встречу`,code:`checks = [True, False, True]
total = 0
passed = 0
for check in checks:
    total += 1
    if check:
        passed += 1
left = total - passed
percent = round(passed / total * 100, 1)
print(total, passed, left, percent)`}),(0,y.jsxs)(`p`,{children:[`В независимом примере регистрации три отметки, две истинны. Код напечатает `,(0,y.jsx)(`code`,{children:`3 2 1 66.7`}),`: сначала цикл получает счётчики, затем арифметика получает долю, затем интерфейс выводит числа. Здесь не используются функции Planner, поэтому пример показывает принцип и не выдаёт готовую реализацию.`]}),(0,y.jsxs)(`p`,{children:[`В собственном `,(0,y.jsx)(`code`,{children:`main.py`}),` две функции определяем вне `,(0,y.jsx)(`code`,{children:`run()`}),`, чтобы вызвать их и из редактора, и из меню. Сам `,(0,y.jsx)(`code`,{children:`tasks`}),` остаётся локальным внутри `,(0,y.jsx)(`code`,{children:`run()`}),`; для проверки функций вне меню передаём им отдельный небольшой аргумент, а для проверки команды выполняем `,(0,y.jsx)(`code`,{children:`stats`}),`в одном запуске Planner. Ветвь выводит четыре подписи: «Всего», «Выполнено», «Осталось», «Процент выполнения».`]}),(0,y.jsx)(t,{rows:[[`Пустой список`,`Всего: 0; Выполнено: 0; Осталось: 0; Процент выполнения: 0.0%`],[`После поиска одной из двух`,`Всего: 2; Выполнено: 1; Осталось: 1; Процент выполнения: 50.0%`],[`Добавлена новая открытая`,`Всего: 3; Выполнено: 1; Осталось: 2; Процент выполнения: 33.3%`]]}),(0,y.jsxs)(`p`,{children:[`Две проверки обнаруживают разные ошибки. Когда нет ни одной задачи, ожидаем четыре нуля, а процент выводим как `,(0,y.jsx)(`code`,{children:`0.0%`}),`: это проверяет защиту от деления на ноль. Когда задачи есть, сначала отмечаем одну из двух как выполненную, затем ищем её по названию и вызываем `,(0,y.jsx)(`code`,{children:`stats`}),`. Если видим `,(0,y.jsx)(`code`,{children:`100.0%`}),`, значит подсчитали одну найденную карточку, забыв вторую. Правильные `,(0,y.jsx)(`code`,{children:`50.0%`}),` подтверждают использование полного списка. После третьей невыполненной карточки результат должен стать `,(0,y.jsx)(`code`,{children:`33.3%`}),`, хотя завершённая задача по-прежнему одна.`]})]}),(0,y.jsxs)(s,{number:`07`,title:`Что мы будем делать в практике`,children:[(0,y.jsxs)(o,{children:[`Работаем в том же локальном StudyHub и продолжаем один `,(0,y.jsx)(`code`,{children:`main.py`}),`. Команда `,(0,y.jsx)(`code`,{children:`stats`}),` уже должна быть видна в меню, но её ветвь пока заглушка. Сверим свой проект с этой точкой старта, затем отдельно проверим функции и заменим заглушку. Пустой список проверяем до других сценариев.`]}),(0,y.jsx)(u,{variant:`connected`,items:[{title:`Мы напишем build_statistics(tasks)`,description:`Получим словарь с total, completed, left для пустого, смешанного и полностью выполненного набора; исходные карточки не изменятся.`},{title:`Мы напишем completion_percent(statistics)`,description:`Получим 0.0 при total=0, 33.3 для одной из трёх задач и 100.0 для всех выполненных; ответ останется числом.`},{title:`Мы подключим stats в прежнем run()`,description:`Увидим четыре подписанных значения по полному tasks, даже если search недавно показал одну карточку.`},{title:`Мы повторим done и добавим задачу`,description:`Повторный done не изменит completed; новое add изменит total и left, а процент пересчитается.`}]}),(0,y.jsxs)(`p`,{children:[`В редакторе платформы напишем определения функций над готовыми проверочными вызовами. Отдадим из первой именно словарь с тремя ключами, а во вторую передадим один этот словарь. Отдельные вызовы проверяют договор функций; проверочные строки из стартера в локальный `,(0,y.jsx)(`code`,{children:`main.py`}),` не переносим.`]}),(0,y.jsxs)(`p`,{children:[`В настоящем Planner проверим цепочку: пустой `,(0,y.jsx)(`code`,{children:`stats`}),` → две `,(0,y.jsx)(`code`,{children:`add`}),` → один`,(0,y.jsx)(`code`,{children:`done`}),` → `,(0,y.jsx)(`code`,{children:`search`}),` → `,(0,y.jsx)(`code`,{children:`stats`}),` → повторный `,(0,y.jsx)(`code`,{children:`done`}),` → новая`,(0,y.jsx)(`code`,{children:`add`}),` → `,(0,y.jsx)(`code`,{children:`stats`}),`. Прежде чем вводить команду, предскажем числа. Команды `,(0,y.jsx)(`code`,{children:`list`}),`и `,(0,y.jsx)(`code`,{children:`exit`}),` также должны продолжать работать; полную регрессию и README оставим занятию 20.`]})]})]})}export{b as Lesson19_1};